### Objective
Build a production-grade E-Commerce Product Showcase & Animated Transition Hub in Flutter. The application demonstrates real-world animation choreographies: a shared element Hero animation with custom flightShuttleBuilder into a product detail screen, bespoke PageRouteBuilder transitions with coordinated secondary animations, and an interactive state-driven AnimatedSwitcher with custom dual-direction slide-fade transitions.

```dart
import 'package:flutter/material.dart';

void main() {
  runApp(const AnimationShowcaseApp());
}

class AnimationShowcaseApp extends StatelessWidget {
  const AnimationShowcaseApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Advanced Animation Masterclass',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.deepOrange,
        useMaterial3: true,
      ),
      home: const ProductCatalogScreen(),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODEL
// ─────────────────────────────────────────────────────────────────────────────

class ProductItem {
  final String id;
  final String name;
  final String category;
  final double price;
  final Color badgeColor;
  final IconData icon;

  const ProductItem({
    required this.id,
    required this.name,
    required this.category,
    required this.price,
    required this.badgeColor,
    required this.icon,
  });
}

const sampleProducts = [
  ProductItem(
    id: 'prod_101',
    name: 'Impeller High-Performance GPU Rig',
    category: 'Hardware Accelerators',
    price: 1899.99,
    badgeColor: Colors.deepPurple,
    icon: Icons.developer_board_rounded,
  ),
  ProductItem(
    id: 'prod_102',
    name: 'Reactive Stream Sensor Watch',
    category: 'Wearable Telemetry',
    price: 449.50,
    badgeColor: Colors.teal,
    icon: Icons.watch_rounded,
  ),
  ProductItem(
    id: 'prod_103',
    name: 'Skeletal Mesh Vector Rig',
    category: 'Motion Design Hardware',
    price: 799.00,
    badgeColor: Colors.deepOrange,
    icon: Icons.animation_rounded,
  ),
];

// ─────────────────────────────────────────────────────────────────────────────
// 2. PRODUCT CATALOG SCREEN (Source of Hero & AnimatedSwitcher)
// ─────────────────────────────────────────────────────────────────────────────

class ProductCatalogScreen extends StatefulWidget {
  const ProductCatalogScreen({super.key});

  @override
  State<ProductCatalogScreen> createState() => _ProductCatalogScreenState();
}

class _ProductCatalogScreenState extends State<ProductCatalogScreen> {
  int _cartCount = 0;
  bool _isCompactView = false;

  void _addToCart() {
    setState(() => _cartCount++);
  }

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Enterprise Motion Catalog'),
        actions: [
          IconButton(
            icon: Icon(_isCompactView ? Icons.view_agenda : Icons.grid_view),
            tooltip: 'Toggle Layout',
            onPressed: () => setState(() => _isCompactView = !_isCompactView),
          ),
          // AnimatedSwitcher driving the Cart Badge
          Padding(
            padding: const EdgeInsets.only(right: 16.0),
            child: Center(
              child: Stack(
                alignment: Alignment.topRight,
                children: [
                  IconButton(
                    icon: const Icon(Icons.shopping_bag_outlined),
                    onPressed: () {},
                  ),
                  if (_cartCount > 0)
                    Positioned(
                      right: 4,
                      top: 4,
                      child: AnimatedSwitcher(
                        duration: const Duration(milliseconds: 300),
                        transitionBuilder: (child, animation) {
                          return ScaleTransition(
                            scale: CurvedAnimation(
                              parent: animation,
                              curve: Curves.elasticOut,
                            ),
                            child: child,
                          );
                        },
                        child: Container(
                          key: ValueKey<int>(_cartCount),
                          padding: const EdgeInsets.all(5),
                          decoration: BoxDecoration(
                            color: colorScheme.error,
                            shape: BoxShape.circle,
                          ),
                          constraints: const BoxConstraints(minWidth: 18, minHeight: 18),
                          child: Text(
                            '$_cartCount',
                            style: TextStyle(
                              color: colorScheme.onError,
                              fontSize: 10,
                              fontWeight: FontWeight.bold,
                            ),
                            textAlign: TextAlign.center,
                          ),
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ],
      ),
      body: ListView.builder(
        padding: const EdgeInsets.all(16),
        itemCount: sampleProducts.length,
        itemBuilder: (context, index) {
          final product = sampleProducts[index];
          return _buildProductCard(context, product);
        },
      ),
    );
  }

  Widget _buildProductCard(BuildContext context, ProductItem product) {
    final colorScheme = Theme.of(context).colorScheme;

    return Card(
      margin: const EdgeInsets.only(bottom: 16),
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
      elevation: 2,
      child: InkWell(
        borderRadius: BorderRadius.circular(20),
        onTap: () => _openProductDetail(context, product),
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: Row(
            children: [
              // HERO 1: Product Icon with Hero Tag and Material wrapper
              Hero(
                tag: 'product_icon_${product.id}',
                flightShuttleBuilder: (flightContext, animation, direction, fromContext, toContext) {
                  // Custom flight rotation
                  return RotationTransition(
                    turns: animation.drive(Tween(begin: 0.0, end: 0.25)),
                    child: toContext.widget,
                  );
                },
                child: Material(
                  type: MaterialType.transparency,
                  child: CircleAvatar(
                    radius: 36,
                    backgroundColor: product.badgeColor.withValues(alpha: 0.15),
                    child: Icon(product.icon, size: 36, color: product.badgeColor),
                  ),
                ),
              ),
              const SizedBox(width: 16),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      product.category.toUpperCase(),
                      style: TextStyle(
                        fontSize: 10,
                        fontWeight: FontWeight.bold,
                        letterSpacing: 1.1,
                        color: colorScheme.primary,
                      ),
                    ),
                    const SizedBox(height: 4),
                    // HERO 2: Product Name
                    Hero(
                      tag: 'product_name_${product.id}',
                      child: Material(
                        type: MaterialType.transparency,
                        child: Text(
                          product.name,
                          style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
                        ),
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      '\$${product.price.toStringAsFixed(2)}',
                      style: const TextStyle(fontWeight: FontWeight.w900, fontSize: 16),
                    ),
                  ],
                ),
              ),
              IconButton.filledTonal(
                icon: const Icon(Icons.add_shopping_cart),
                onPressed: _addToCart,
              ),
            ],
          ),
        ),
      ),
    );
  }

  void _openProductDetail(BuildContext context, ProductItem product) {
    // Custom PageRouteBuilder with curved slide & elevation transform
    Navigator.of(context).push(
      PageRouteBuilder(
        transitionDuration: const Duration(milliseconds: 600),
        reverseTransitionDuration: const Duration(milliseconds: 450),
        pageBuilder: (context, animation, secondaryAnimation) {
          return ProductDetailScreen(
            product: product,
            onAddToCart: _addToCart,
          );
        },
        transitionsBuilder: (context, animation, secondaryAnimation, child) {
          final curved = CurvedAnimation(
            parent: animation,
            curve: Curves.fastOutSlowIn,
          );
          return FadeTransition(
            opacity: curved,
            child: SlideTransition(
              position: Tween<Offset>(
                begin: const Offset(0.0, 0.12),
                end: Offset.zero,
              ).animate(curved),
              child: child,
            ),
          );
        },
      ),
    );
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. PRODUCT DETAIL SCREEN (Destination of Hero)
// ─────────────────────────────────────────────────────────────────────────────

class ProductDetailScreen extends StatelessWidget {
  final ProductItem product;
  final VoidCallback onAddToCart;

  const ProductDetailScreen({
    super.key,
    required this.product,
    required this.onAddToCart,
  });

  @override
  Widget build(BuildContext context) {
    final colorScheme = Theme.of(context).colorScheme;

    return Scaffold(
      appBar: AppBar(
        title: const Text('Product Architecture'),
      ),
      body: ListView(
        padding: const EdgeInsets.all(24),
        children: [
          // Destination Hero with large dimensions
          Center(
            child: Hero(
              tag: 'product_icon_${product.id}',
              child: Material(
                type: MaterialType.transparency,
                child: CircleAvatar(
                  radius: 72,
                  backgroundColor: product.badgeColor.withValues(alpha: 0.15),
                  child: Icon(product.icon, size: 72, color: product.badgeColor),
                ),
              ),
            ),
          ),
          const SizedBox(height: 28),
          Center(
            child: Hero(
              tag: 'product_name_${product.id}',
              child: Material(
                type: MaterialType.transparency,
                child: Text(
                  product.name,
                  textAlign: TextAlign.center,
                  style: Theme.of(context).textTheme.headlineSmall?.copyWith(
                        fontWeight: FontWeight.bold,
                      ),
                ),
              ),
            ),
          ),
          const SizedBox(height: 12),
          Center(
            child: Text(
              '\$${product.price.toStringAsFixed(2)}',
              style: TextStyle(
                fontSize: 28,
                fontWeight: FontWeight.w900,
                color: colorScheme.primary,
              ),
            ),
          ),
          const SizedBox(height: 32),
          Card(
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
            child: const Padding(
              padding: EdgeInsets.all(18.0),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Hero Flight Architecture', style: TextStyle(fontWeight: FontWeight.bold, fontSize: 14)),
                  SizedBox(height: 8),
                  Text(
                    '• The icon and headline flew across routes using MaterialRectArcTween.\n'
                    '• The flightShuttleBuilder applied a smooth rotation during flight.\n'
                    '• Material(type: MaterialType.transparency) prevents yellow text underlines.',
                    style: TextStyle(fontSize: 12, height: 1.5, color: Colors.black87),
                  ),
                ],
              ),
            ),
          ),
          const SizedBox(height: 32),
          FilledButton.icon(
            onPressed: () {
              onAddToCart();
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text('Added to Cart! Notice badge scale animation.'),
                  behavior: SnackBarBehavior.floating,
                ),
              );
            },
            style: FilledButton.styleFrom(padding: const EdgeInsets.symmetric(vertical: 16)),
            icon: const Icon(Icons.add_shopping_cart),
            label: const Text('Add to Cart & Trigger Badge'),
          ),
        ],
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Shared Element Hero Pairing**:
   `ProductCatalogScreen` and `ProductDetailScreen` share matching `tag` strings (`'product_icon_${product.id}'` and `'product_name_${product.id}'`). Tapping the card instructs `HeroController` to lift both elements into the `Overlay` and calculate curved arc trajectories.
2. **Custom Flight Shuttle (`flightShuttleBuilder`)**:
   On the product icon hero, `flightShuttleBuilder` injects a `RotationTransition` that rotates the icon by a quarter turn in-flight, showcasing custom intermediate transformation without altering either screen's static layout.
3. **Preserving Text Rendering in Heroes**:
   Wrapping the `Text` widgets inside `Material(type: MaterialType.transparency)` guarantees that the text doesn't display the notorious yellow double underline during flight (which occurs when text lacks an ancestor `Material` widget in the overlay).
4. **Bespoke Route Transition with `PageRouteBuilder`**:
   `_openProductDetail` uses `PageRouteBuilder` combining `FadeTransition` and a fractional `SlideTransition` with `Curves.fastOutSlowIn`, creating an elegant vertical entrance that coordinates with the flying hero.
5. **Declarative State Transitions (`AnimatedSwitcher`)**:
   The cart counter in the app bar is wrapped in `AnimatedSwitcher`. When `_cartCount` increments, the `ValueKey<int>(_cartCount)` forces the switcher to recognize a child change and play an elastic bounce transition.
